labels=['HF reference','EXL3 3bpw','EXL2 4bpw']
def filt(mask):
 return [s for s in labels if not mask or any(m.upper() in s.upper() for m in mask.split(';'))]
for mask in [None,'exl3;exl2','exl3;',' exl3','missing']:
 print(repr(mask),filt(mask))
def key(args): return str((json.dumps(args,sort_keys=True),json.dumps({},sort_keys=True)))
a=({'dataset':'wiki2'},{'label':'EXL3'},'ref.safetensors')
print('old_clear_matches',key(a[:2])==key(a),'new_clear_matches',key(a)==key(a))
try: print(0.0/0.0)
except ZeroDivisionError: print('no_reference_finalization: ZeroDivisionError')

